package org.springframework.samples.petclinic.rest.advice;

/**
 * Raised when an owner is created with the same last name and address (compared case-insensitively
 * with collapsed whitespace) as an existing owner, and the request did not set {@code sharesHousehold}
 * to acknowledge the shared household. Maps to a 409 Conflict response.
 */
public class DuplicateOwnerHouseholdException extends RuntimeException {

    private final String lastName;

    private final String address;

    public DuplicateOwnerHouseholdException(String lastName, String address) {
        super("An owner with last name " + lastName + " at address " + address + " already exists");
        this.lastName = lastName;
        this.address = address;
    }

    public String getLastName() {
        return this.lastName;
    }

    public String getAddress() {
        return this.address;
    }
}

